import threading
lock = threading.RLock()
def recursive(n):
    if n == 0:
        return 'done'
    with lock:
        return recursive(n-1)
print(recursive(3))

import threading

class Worker(threading.Thread):
    def __init__(self):
        super().__init__()
        self._return = None
    def run(self):
        self._return = 'result'
    def join(self, timeout=None):
        super().join(timeout)
        return self._return

t = Worker()
t.start()
print(t.join())

