import threading

barrier = threading.Barrier(3)
def worker():
    try:
        gen = barrier.wait(timeout=0.5)
        print(gen)
    except threading.BrokenBarrierError:
        print('broken')

threads = [threading.Thread(target=worker) for _ in range(2)]
for t in threads:
    t.start()
for t in threads:
    t.join()
